export async function loadMallas(prisma, tenantId) {
  if (tenantId !== 'UPU') return { skipped: true, reason: `tenant ${tenantId} no UPU` };

  const institution = await prisma.institution.findFirst({ where: { code: 'UPU-MAIN' } });
  if (!institution) return { skipped: true, reason: 'institution UPU-MAIN no encontrada' };
  const wf = await prisma.workflow.findFirst({ where: { name: 'activity-standard', institutionId: institution.id } });
  const pub = await prisma.workflowStatus.findFirst({ where: { code: 'PUB', institutionId: institution.id } });
  // executionUnit: Faculty propia de UPU-MAIN. El modelo destino (develop) usa recordType=Faculty,
  // NO 'AcademicExecution' (UPONE-1456 §3.1). Find-or-create + anclaje via rt__Faculty__OrgUnit.
  // Mismo code que usa _data-offerings.js -> una sola Faculty compartida, idempotente.
  let execUnit = await prisma.orgUnit.findFirst({ where: { code: 'UPU-FAC-ING' } });
  if (!execUnit) execUnit = await prisma.orgUnit.create({ data: {
    organizationId: institution.organizationId, recordType: 'Faculty',
    name: 'Facultad de Ingenieria', code: 'UPU-FAC-ING', type: 'Faculty', status: 'Active' } });
  await prisma.rt__Faculty__OrgUnit.upsert({
    where: { OrgUnitId: execUnit.id },
    create: { OrgUnitId: execUnit.id, institutionId: institution.id },
    update: { institutionId: institution.id } });

  // 1. Asignaturas de la malla (idempotente por code @unique)
  const actByCode = {};
  let actCreated = 0;
  for (const a of MALLA_ACTIVITIES) {
    let act = await prisma.activity.findFirst({ where: { code: a.code } });
    if (!act) {
      act = await prisma.activity.create({ data: {
        name: a.name, code: a.code, recordType: 'Course', version: 1, language: 'es',
        credits: a.credits, programLevel: a.programLevel,
        executionUnitId: execUnit ? execUnit.id : null,
        workflowId: wf ? wf.id : null, currentStatusId: pub ? pub.id : null, versionLabel: 'v2026-actual',
      }});
      actCreated++;
    }
    actByCode[a.code] = act.id;
  }

  // 2. Planes por code
  const planByCode = {};
  for (const c of CATEGORIES) {
    if (planByCode[c.planCode]) continue;
    planByCode[c.planCode] = await prisma.curriculum.findFirst({ where: { code: c.planCode, institutionId: institution.id } });
  }

  // 3. requirementCategory (idempotente por curriculumId + code)
  const catByKey = {}; // `${planCode}|${code}` -> id
  let catCreated = 0;
  for (const c of CATEGORIES) {
    const plan = planByCode[c.planCode];
    if (!plan) continue;
    let cat = await prisma.requirementCategory.findFirst({ where: { curriculumId: plan.id, code: c.code } });
    if (!cat) {
      cat = await prisma.requirementCategory.create({ data: {
        curriculumId: plan.id, name: c.name, code: c.code, minCredits: c.minCredits,
        maxCredits: c.maxCredits, position: c.position, color: c.color, icon: c.icon,
      }});
      catCreated++;
    }
    catByKey[`${c.planCode}|${c.code}`] = cat.id;
  }

  // 4. planEntry (idempotente por planId + activityId + period + position)
  let entCreated = 0;
  for (const e of PLAN_ENTRIES) {
    const plan = planByCode[e.planCode] || (planByCode[e.planCode] = await prisma.curriculum.findFirst({ where: { code: e.planCode, institutionId: institution.id } }));
    if (!plan) continue;
    const activityId = actByCode[e.activityCode];
    const categoryId = catByKey[`${e.planCode}|${e.categoryCode}`];
    if (!activityId || !categoryId) continue;
    const existing = await prisma.planEntry.findFirst({ where: { planId: plan.id, activityId, period: e.period, position: e.position } });
    if (existing) continue;
    await prisma.planEntry.create({ data: {
      planId: plan.id, activityId, categoryId, kind: e.kind, period: e.period, position: e.position, credits: e.credits,
    }});
    entCreated++;
  }

  return { actCreated, catCreated, entCreated, activities: MALLA_ACTIVITIES.length, categories: CATEGORIES.length, entries: PLAN_ENTRIES.length };
}
